require_once __DIR__.'/../config/database.php';require_once __DIR__.'/helpers.php';$a=chat_actor($pdo);$role=$_GET['role']??'';$id=(int)($_GET['id']??0);chat_target_allowed($pdo,$a,$role,$id);
$q=$pdo->prepare('SELECT * FROM messages WHERE deleted_at IS NULL AND ((sender_role=? AND sender_id=? AND receiver_role=? AND receiver_id=?) OR (sender_role=? AND sender_id=? AND receiver_role=? AND receiver_id=?)) ORDER BY created_at ASC,id ASC');$q->execute([$a['role'],$a['id'],$role,$id,$role,$id,$a['role'],$a['id']]);$messages=$q->fetchAll();foreach($messages as &$m){$m['id']=(int)$m['id'];$m['sender_name']=chat_name($pdo,$m['sender_role'],(int)$m['sender_id']);}$read=$pdo->prepare('UPDATE messages SET read_at=NOW() WHERE receiver_role=? AND receiver_id=? AND sender_role=? AND sender_id=? AND read_at IS NULL');$read->execute([$a['role'],$a['id'],$role,$id]);json_response(['success'=>true,'messages'=>$messages]);
